example.code:
using var reader = new StringReader("Name,Age\nJohn,30\nJane,25");
var csvReader = new CsvReader(reader) { HasHeaderRow = true };

while (await csvReader.ReadRowAsync() is { } row)
{
    Console.WriteLine($"{row["Name"]} is {row["Age"]} years old");
}

using var reader = new StringReader("Name,Age\nJohn,30");
var csvReader = new CsvReader(reader) { HasHeaderRow = true };
var row = await csvReader.ReadRowAsync();

// Access by column name
Console.WriteLine(row["Name"]); // John

// Access by column index
Console.WriteLine(row[1]); // 30

using var writer = new StringWriter();
var csvWriter = new CsvWriter(writer);

await csvWriter.WriteRowAsync("Name", "Age");
await csvWriter.WriteRowAsync("John", "30");
await csvWriter.WriteRowAsync("Jane", "25");

Console.WriteLine(writer.ToString());
// Output:
// Name,Age
// John,30
// Jane,25
